(function(root){
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmt=(v,n=2)=>Number.isFinite(v)?new Intl.NumberFormat('es-ES',{maximumFractionDigits:n}).format(v):'—';
 const date=v=>Number.isFinite(Date.parse(v))?new Intl.DateTimeFormat('es-ES',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Madrid'}).format(new Date(v)):'sin fecha';
 function validate(data){
  if(data?.metadata?.competition!=='LaLiga'||data.metadata.season!=='2026/27'||data.metadata.method!=='ridge_nested_group_cv_v1'||!Array.isArray(data.models)||data.models.length!==8||new Set(data.models.map(m=>m.key)).size!==8)throw Error('Informe Fantasy inválido.');
  for(const m of data.models){if(!Number.isInteger(m.n)||m.n<0||!Array.isArray(m.coefficients)||!Array.isArray(m.players)||!['fitted','insufficient_sample'].includes(m.status))throw Error('Modelo Fantasy inválido.');if(m.status==='fitted'&&(!['mae','rmse','r2'].every(k=>Number.isFinite(m.validation?.[k]))||m.coefficients.some(c=>!Number.isFinite(c.ridge_standardized)||!Number.isFinite(c.ridge_raw))))throw Error('Coeficientes inválidos.');}
  return data;
 }
 function coefficientsChart(model){
  const rows=[...model.coefficients].sort((a,b)=>Math.abs(b.ridge_standardized)-Math.abs(a.ridge_standardized)),max=Math.max(...rows.map(c=>Math.abs(c.ridge_standardized)),1),height=rows.length*29+36;
  return '<svg class="reg-chart" viewBox="0 0 900 '+height+'" role="img" aria-label="Asociación Ridge: puntos Fantasy por una desviación estándar, controlando las otras variables"><line x1="610" y1="0" x2="610" y2="'+(height-25)+'" stroke="currentColor" opacity=".4"/>'+rows.map((c,i)=>{const value=c.ridge_standardized,width=Math.abs(value)/max*240,y=i*29+8;return '<g><title>'+esc(c.label)+': '+fmt(value)+' puntos por 1 DE; '+fmt(c.ridge_raw,4)+' por unidad</title><text x="5" y="'+(y+12)+'">'+esc(c.label.length>47?c.label.slice(0,44)+'…':c.label)+'</text><rect x="'+(value>=0?610:610-width)+'" y="'+y+'" width="'+width+'" height="16" fill="'+(c.control?'#9ba8a0':value>=0?'#c4f568':'#e9977b')+'"/><text x="890" y="'+(y+12)+'" text-anchor="end">'+fmt(value)+'</text></g>';}).join('')+'<text x="610" y="'+(height-3)+'" text-anchor="middle">0 · puntos por 1 DE</text></svg>';
 }
 function scatter(model){
  const values=model.players.flatMap(p=>[p.points,p.predicted_oof]),lo=Math.min(...values,0),hi=Math.max(...values,1),scale=v=>45+(v-lo)/(hi-lo)*500,y=v=>280-(v-lo)/(hi-lo)*235;
  return '<svg class="reg-scatter" viewBox="0 0 600 330" role="img" aria-label="Puntos reales frente a predicciones de validación, con equipos separados"><line x1="45" y1="280" x2="545" y2="45" stroke="#929e95" stroke-dasharray="5 5"/>'+model.players.map(p=>'<circle cx="'+scale(p.points)+'" cy="'+y(p.predicted_oof)+'" r="4" fill="#c4f568" opacity=".65"><title>'+esc(p.name)+' · '+esc(p.team)+' · reales '+fmt(p.points)+'; predichos '+fmt(p.predicted_oof)+'</title></circle>').join('')+'<text x="300" y="318" text-anchor="middle">Puntos Fantasy reales · '+fmt(lo,0)+' a '+fmt(hi,0)+'</text><text x="12" y="28">Predicción fuera de muestra</text></svg>';
 }
 function overview(data){
  const fitted=data.models.filter(m=>m.status==='fitted');
  return '<div class="reg-intro"><span class="badge">LaLiga · 2026/27 · análisis exploratorio</span><h2>Qué se asocia con los puntos de LaLiga Fantasy</h2><p>Ejes estadísticos del score, amarillas, expulsiones y penaltis provocados. Objetivo: puntos acumulados. Cada modelo controla los minutos Fantasy.</p><p class="sub">'+data.metadata.matched+' cruces únicos por nombre y club de '+data.metadata.grada_players+' jugadores GRADA · '+data.metadata.unmatched+' sin cruce · '+(data.metadata.unclassified||0)+' sin perfil · '+fitted.length+' modelos ajustados · '+fitted.reduce((n,m)=>n+m.n,0)+' jugadores en sus muestras.</p><p class="sub">Captura Fantasy: '+esc(date(data.metadata.fantasy.captured_at))+' (Madrid). FotMob analítico: '+esc(date(data.metadata.analysis?.FotMob?.imported_at))+' (Madrid). Cálculo: '+esc(date(data.metadata.generated_at))+'. La captura analítica reciente de LaLiga es independiente de los rankings de GRADA; no incorpora torneos ni cambia sus scores.</p><div class="reg-warning">Asociación, no causalidad. Los coeficientes dependen de las variables incluidas y pueden cambiar de signo por correlación. La muestra exige 200 minutos, datos completos, fechas próximas y minutos compatibles; no se rellenan ausencias con cero. Los PJ de ambas fuentes no tienen una equivalencia demostrada.</div><details><summary>Ver jugadores sin cruce inequívoco</summary><div class="tablewrap"><table><thead><tr><th>Jugador GRADA</th><th>Equipo</th><th>Motivo</th></tr></thead><tbody>'+data.unmatched.map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+esc(p.team)+'</td><td>'+esc(p.ambiguous?'Coincidencia ambigua':p.roleConflict?'Posición de portero incompatible':'Sin coincidencia única de nombre y club')+'</td></tr>').join('')+'</tbody></table></div></details></div>';
 }
 function model(data,key){
  const m=data.models.find(m=>m.key===key);if(!m)return '';
  const quality='<details><summary>Cobertura y exclusiones · '+m.n+' / '+m.matched+' cruces del perfil</summary><p>Los perfiles son los mismos que en el score de GRADA. Los valores explicativos proceden solo de la captura analítica de LaLiga. Amarillas, roja directa + doble amarilla y penaltis provocados son recuentos Fantasy por sus propios 90 minutos; nunca se usan las columnas de puntos por acción como predictores.</p><p>Compatibilidad aproximada: capturas a menos de 24 horas y diferencia de minutos ≤ máx(5 min, 1 %). No sustituye una conciliación partido por partido. PJ iguales en '+(m.same_reported_matches??0)+' de '+m.n+' casos; la diferencia no se usa para asumir eventos distintos.</p><ul>'+Object.entries(m.exclusion_counts).sort((a,b)=>b[1]-a[1]).map(([reason,n])=>'<li>'+esc(reason)+': '+n+'</li>').join('')+'</ul><div class="tablewrap"><table><thead><tr><th>Excluido</th><th>Equipo</th><th>Motivos</th></tr></thead><tbody>'+m.excluded.map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+esc(p.team)+'</td><td>'+esc(p.reasons.join('; '))+'</td></tr>').join('')+'</tbody></table></div></details>';
  if(m.status!=='fitted')return '<article class="panel reg-model"><h3>'+esc(m.label)+'</h3><p class="reg-warning">Muestra insuficiente: '+m.n+' casos completos. '+esc(m.reason)+'</p>'+quality+'</article>';
  const cards=[['Muestra',m.n+' jugadores · '+m.clubs+' equipos'],['MAE de validación',fmt(m.validation.mae)+' puntos'],['R² de validación',fmt(m.validation.r2,3)],['MAE solo minutos',fmt(m.minutes_only.mae)+' puntos']];
  return '<article class="panel reg-model"><h3>'+esc(m.label)+'</h3><div class="reg-metrics">'+cards.map(([label,value])=>'<div><span>'+esc(label)+'</span><strong>'+esc(value)+'</strong></div>').join('')+'</div><p>Ridge con regularización α = '+fmt(m.alpha)+'. Validación externa en cinco grupos de equipos; la regularización se elige dentro de cada entrenamiento. MAE indica el error absoluto medio en jugadores de equipos no vistos.</p>'+(m.n<40?'<p class="reg-warning">Muestra pequeña: interpreta los coeficientes con especial cautela.</p>':'')+'<h4>Asociación por variable · puntos por 1 desviación estándar</h4><p class="sub">Cada barra cambia una variable manteniendo las demás fijas en la ecuación. El control de minutos aparece en gris. Una barra negativa no demuestra que una acción perjudique al jugador.</p>'+coefficientsChart(m)+'<div class="tablewrap"><table><thead><tr><th>Variable</th><th>Ridge · pts/1 DE</th><th>Ridge · pts/unidad</th><th>Signo estable</th><th>OLS · pts/1 DE</th><th>IC 95 % OLS</th><th>q OLS</th><th>VIF</th></tr></thead><tbody>'+m.coefficients.map(c=>'<tr><td>'+esc(c.label)+'</td><td>'+fmt(c.ridge_standardized)+'</td><td>'+fmt(c.ridge_raw,4)+'</td><td>'+fmt(c.sign_stability*100,0)+' %</td><td>'+fmt(c.ols_standardized)+'</td><td>'+(c.ols_ci?fmt(c.ols_ci[0])+' a '+fmt(c.ols_ci[1]):'—')+'</td><td>'+fmt(c.ols_q,4)+'</td><td>'+fmt(c.vif,1)+(c.vif>10?' · alto':'')+'</td></tr>').join('')+'</tbody></table></div><p class="sub">DE = desviación estándar de esa variable. Signo estable = proporción de los cinco entrenamientos con el mismo signo. VIF alto indica colinealidad. Los intervalos pertenecen a OLS, no a Ridge; q corrige comparaciones múltiples. '+(m.ols_status==='estimated'?'OLS usa errores agrupados por equipo.':'No se publican intervalos OLS: '+(m.ols_status==='rank_deficient'?'variables linealmente dependientes.':'muestra insuficiente para una inferencia estable.'))+'</p>'+(m.constant_features.length?'<p class="sub">Sin variación en esta muestra, no estimables: '+m.constant_features.map(key=>esc(m.feature_labels?.[key]||key)).join(', ')+'. No equivale a ausencia de efecto.</p>':'')+'<h4>Predicción frente a puntos observados</h4>'+scatter(m)+'<details><summary>Predicciones de validación por jugador</summary><div class="tablewrap"><table><thead><tr><th>Jugador</th><th>Equipo</th><th>Puntos reales</th><th>Predicción de validación</th><th>Residuo</th></tr></thead><tbody>'+m.players.map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+esc(p.team)+'</td><td>'+fmt(p.points)+'</td><td>'+fmt(p.predicted_oof)+'</td><td>'+fmt(p.residual_oof)+'</td></tr>').join('')+'</tbody></table></div></details>'+quality+'</article>';
 }
 let pending;
 async function open(document,fetcher=root.fetch.bind(root)){
  const node=document.querySelector('#fantasy-body');
  try{
   if(!pending)pending=fetcher('downloads/fantasy-regression-laliga-2026-27.json',{cache:'no-cache',credentials:'same-origin'}).then(r=>{if(!r.ok)throw Error('Informe no disponible');return r.json();}).then(validate).catch(e=>{pending=null;throw e;});
   const data=await pending;
   node.innerHTML=overview(data)+'<div class="reg-controls"><label>Perfil del score <select id="fantasy-profile">'+data.models.map(m=>'<option value="'+esc(m.key)+'"'+(m.key==='DEL'?' selected':'')+'>'+esc(m.label)+' · n='+m.n+'</option>').join('')+'</select></label><a class="btn" href="downloads/fantasy-regression-laliga-2026-27.html" download>Descargar informe</a><a class="linkbtn" href="downloads/fantasy-regression-laliga-2026-27.csv" download>Datos del cruce (CSV)</a><a class="linkbtn" href="downloads/fantasy-regression-input-laliga-2026-27.json" download>Datos y procedencia (JSON)</a></div><div id="fantasy-model"></div>';
   const select=document.querySelector('#fantasy-profile'),render=()=>{document.querySelector('#fantasy-model').innerHTML=model(data,select.value||'DEL');};select.onchange=render;render();
  }catch(_){node.innerHTML='<p class="reg-warning">No se ha podido cargar el informe de LaLiga. Vuelve a abrir este apartado para reintentar.</p>';}
 }
 const api={validate,overview,model,open};if(typeof module==='object'&&module.exports)module.exports=api;else root.GradaFantasy=api;
})(typeof window==='object'?window:globalThis);
